const productFormat=(p,format='unit')=>p.cat==='Combos'?'COMBO':format==='box'?`CAJA X${p.boxQuantity}`:format==='pair'?'PACK X2':'UNIDADES';
const offerDate=p=>p.offerUntil?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'2-digit'}).format(new Date(p.offerUntil).getTime()-1):'';
const stockStatus=p=>{if(p.stock===undefined||p.stock===null||p.stock==='')return'<span class="stockStatus pending">Stock a confirmar</span>';const stock=Number(p.stock),minimum=Number(p.minimumStock||p.stockMinimum||0);if(stock<=0)return'<span class="stockStatus unavailable">Consultar disponibilidad</span>';if(stock<=Math.max(minimum,5))return'<span class="stockStatus low">Pocas unidades</span>';return'<span class="stockStatus available">Disponible</span>'};
const amountField=(p,format,label)=>`<label class="amountField"><span>${label}</span><div class="cardQty" aria-label="${label} de ${p.name}"><button type="button" data-card-step="-1" aria-label="Restar ${label.toLowerCase()}">−</button><input type="number" min="0" max="999" value="0" inputmode="numeric" data-amount-format="${format}" aria-label="Cantidad de ${label.toLowerCase()} de ${p.name}"><button type="button" data-card-step="1" aria-label="Sumar ${label.toLowerCase()}">+</button></div></label>`;
const orderComposer=(p,compact=false)=>{const hint=p.cat==='Combos'?'Completá cuántos combos querés.':p.boxPrice&&!p.boxOnly?'Completá unidades, cajas o ambas.':p.boxOnly?'Completá cuántas cajas querés.':'Completá cuántas unidades querés.';return`<div class="orderComposer${compact?' compactComposer':''}" data-product="${p.id}" data-default-hint="${hint}"><div class="amountFields">${p.boxOnly?'':amountField(p,'unit',p.cat==='Combos'?'Combos':'Unidades')}${p.boxPrice?amountField(p,'box','Cajas'):''}</div><button class="add addQuantities" type="button" data-add-quantities="${p.id}">Agregar al pedido</button><small class="amountHint">${hint}</small></div>`};
function card(p){
  const isCombo=p.cat==='Combos',details=p.comboItems?.length?`<details class="comboDetails"><summary>Ver qué incluye</summary><ul>${p.comboItems.map(item=>`<li>${item}</li>`).join('')}</ul></details>`:'',offerSaving=p.regularPrice&&p.regularPrice>p.price?p.regularPrice-p.price:0,boxSaving=p.boxPrice&&p.boxQuantity&&p.price?p.price*p.boxQuantity-p.boxPrice:0;
  const unitBlock=p.boxOnly?'':p.twoForEnabled?`<div class="purchasePrice pairPurchasePrice"><small>Pack de 2 unidades</small><strong>2 x ${money(p.price*2)}</strong><span>${money(p.price)} cada unidad</span></div>`:`<div class="purchasePrice"><small>Precio por unidad</small><strong>${money(p.price)}</strong></div>`,boxBlock=p.boxPrice?`<div class="purchasePrice boxPurchasePrice"><small>Comprando caja x${p.boxQuantity}</small><strong>${moneyUnit(p.boxUnitPrice)} <em>la unidad</em></strong><span>Total de la caja: ${money(p.boxPrice)}</span>${boxSaving>0?`<b class="savingText">Ahorrás ${money(boxSaving)} por caja</b>`:''}</div>`:'';
  return`<article class="card${isCombo?' comboCard':''}${[1008,1009,1010].includes(Number(p.id))?' wideComboImage':''}${p.featuredOffer?' weeklyOffer':''}">${p.featuredOffer?`<span class="badge${p.regularPrice?'':' featuredBadge'}">${p.regularPrice?`${Math.round((1-p.price/p.regularPrice)*100)}% OFF`:'DESTACADO SEMANAL'}</span>`:''}${p.boxOnly?`<span class="badge">PACK X${p.boxQuantity}</span>`:''}<div class="productImage"><img loading="lazy" src="${p.img}" alt="${p.name}"></div><div class="cardBody">${p.brand?`<small class="brandName">${p.brand}</small>`:''}<h3>${p.name}</h3>${stockStatus(p)}${details}${p.regularPrice?`<div class="offerPriceInfo"><span>Antes <del>${money(p.regularPrice)}</del></span>${offerSaving>0?`<b>Ahorrás ${money(offerSaving)}</b>`:''}</div>`:''}${isCombo||p.offerOnly?`<small class="priceType">${isCombo?'Precio por combo':'Precio especial'}</small><div class="price offerPrice">${money(p.price)}</div>`:`<div class="purchasePrices">${unitBlock}${boxBlock}</div>`}${p.featuredOffer&&offerDate(p)?`<span class="offerUntil">Válido hasta el ${offerDate(p)}</span>`:''}<span class="transfer">${p.boxPrice?'Podés combinar unidades y cajas':'Elegí la cantidad que necesitás'}</span>${orderComposer(p)}</div></article>`
}
function homeComboCard(p){const items=p.comboItems||[];return `<article class="homeComboCard" data-home-combo><div class="homeComboImage"><img loading="lazy" src="${p.img}" alt="${p.name}"><span class="comboImageHint">Tocá para ver qué incluye</span></div><div class="homeComboBody"><small>COMBO FALUCHO</small><h3>${p.name}</h3>${items.length?`<details class="homeComboDetails"><summary>Ver qué incluye <span aria-hidden="true">+</span></summary><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul></details>`:''}<div class="homeComboPrice">${money(p.price)}</div>${orderComposer(p,true)}</div></article>`}
function renderHomeCombos(){const host=document.querySelector('#homeCombos');if(!host)return;const selected=products.filter(p=>p.cat==='Combos').slice(0,6);host.innerHTML=selected.map(homeComboCard).join('')}
function renderHomeHighlights(){const host=document.querySelector('#homeHighlights');if(!host)return;const featuredSlugs=['fideos-mostachol-sol-pampeano-x500gr','vodka-skyy-cosmic-x700ml','speed-xl-x-unidad','azucar-gury-x1kg','aceite-girasol-el-paisano-x900cc','leche-larga-vida-gandara-x1lt','alfajor-super-triple-fantoche-x100gr','cajon-dulce-de-membrillo-7-dias-x5kg','queso-cremoso-4-hermanos-x-horma','aperitivo-fernet-branca-x750ml'];const selected=featuredSlugs.map(slug=>products.find(p=>p.slug===slug)).filter(Boolean);host.innerHTML=selected.map(card).join('')}
function initHighlightRail(){const rail=document.querySelector('#homeHighlights'),buttons=document.querySelectorAll('[data-highlight-scroll]');if(!rail||!buttons.length)return;const update=()=>{const max=rail.scrollWidth-rail.clientWidth;buttons.forEach(button=>button.disabled=Number(button.dataset.highlightScroll)<0?rail.scrollLeft<5:rail.scrollLeft>max-5)};buttons.forEach(button=>button.addEventListener('click',()=>rail.scrollBy({left:Number(button.dataset.highlightScroll)*Math.max(280,rail.clientWidth*.82),behavior:'smooth'})));rail.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update()}
function renderBrandShowcase(){const host=document.querySelector('#brandShowcase');if(!host)return;const preferred=['Gándara','Baggio','Fantoche','Silvia','Esnaola','Molinos Cañuelas','Bahía','Elegante','Coca-Cola','Speed','Campari','Pernod Ricard','Bodega Rutini Wines','Otros'];const available=new Set(products.map(p=>(p.brand||'Otros').trim()||'Otros'));const brands=preferred.filter(brand=>available.has(brand));host.innerHTML=brands.map(brand=>`<button type="button" class="brandTile" data-brand-shop="${brand.replace(/&/g,'&amp;').replace(/"/g,'&quot;')}"><span>${brand.slice(0,2).toUpperCase()}</span><b>${brand}</b><small>Ver productos</small></button>`).join('')}
function filteredProducts(){let list=products.filter(p=>(query||belongsToView(p))&&belongsToBuyer(p));if(activeBrand!=='all')list=list.filter(p=>(p.brand||'Otros')===activeBrand);if(!query&&activeSubcategory!=='all')list=list.filter(p=>subcategoryGroup(p)===activeSubcategory);if(!query&&activeDetail!=='all')list=list.filter(p=>detailGroup(p)===activeDetail);if(query)list=list.filter(p=>normalizedText(p).includes(normalize(query)));if(purchaseMode==='unit')list=list.filter(p=>!p.boxOnly);if(purchaseMode==='box')list=list.filter(p=>Boolean(p.boxPrice||p.boxOnly));if(sortMode==='price-asc')list.sort((a,b)=>(a.boxOnly?a.boxUnitPrice:a.price)-(b.boxOnly?b.boxUnitPrice:b.price));if(sortMode==='price-desc')list.sort((a,b)=>(b.boxOnly?b.boxUnitPrice:b.price)-(a.boxOnly?a.boxUnitPrice:a.price));if(sortMode==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));return list}
function renderCatalog(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',!query&&!buyerMode&&b.dataset.view===activeView));document.querySelectorAll('[data-buyer]').forEach(b=>b.classList.toggle('active',b.dataset.buyer===buyerMode));const buyerNotice=document.querySelector('#buyerNotice');if(buyerNotice){buyerNotice.hidden=!buyerMode;buyerNotice.innerHTML=buyerMode?`<b>Selección para ${buyerMode==='Hogar'?'tu hogar':buyerMode}</b><span>Te mostramos los productos más útiles para este tipo de compra. Podés seguir filtrando o ver todo el catálogo.</span>`:''}const list=filteredProducts();productGrid.innerHTML=list.length?list.slice(0,visibleLimit).map(card).join(''):`<p class="categoryEmpty">${activeView==='Ofertas'&&!query?'Próximamente vas a encontrar acá nuestras mejores ofertas.':'No encontramos productos con esos filtros.'}</p>`;resultsCount.textContent=`${list.length} ${list.length===1?'producto':'productos'}${query?' encontrados':''}`;loadMore.hidden=list.length<=visibleLimit;clearFilters.hidden=activeView==='Ofertas'&&activeSubcategory==='all'&&!buyerMode&&purchaseMode==='all'&&!query&&sortMode==='featured';document.querySelector('#offersNotice').hidden=Boolean(query)||Boolean(buyerMode)||activeView!=='Ofertas'}

const basketData=key=>{const[id,format='unit']=String(key).split(':'),product=products.find(p=>p.id==id);return product?{product,format,price:format==='box'?product.boxPrice:format==='pair'?product.price*2:product.price}:null};
function save(){localStorage.setItem('falucho-cart',JSON.stringify(basket));renderCart()}
function renderCart(){const entries=Object.entries(basket).map(([key,quantity])=>({key,quantity,...basketData(key)})).filter(e=>e.product&&e.price),itemCount=entries.reduce((s,e)=>s+e.quantity,0);cartCount.textContent=itemCount;cartItems.className='cartItems';cartItems.innerHTML=entries.length?entries.map(({key,quantity,product,format,price})=>`<div class="cartRow"><img src="${product.img}" alt=""><div><p><b>${product.name}</b></p><small class="cartFormat">${productFormat(product,format)}</small><span>${money(price*quantity)}</span></div><div class="qty"><button data-qty="${key}" data-d="-1">−</button><b>${quantity}</b><button data-qty="${key}" data-d="1">+</button></div></div>`).join(''):'<p class="empty">Tu carrito está vacío.</p>';const subtotal=entries.reduce((s,e)=>s+e.price*e.quantity,0);discountProgress.innerHTML='<b>Envío a coordinar</b><small>Calculamos el costo según tu localidad antes de confirmar el pedido.</small>';cartTotal.previousElementSibling.textContent='Total estimado';cartTotal.textContent=money(subtotal);floatingCart.querySelector('em').textContent=`${itemCount} ${itemCount===1?'producto':'productos'} · ${money(subtotal)}`}
function openCart(open=true){const cart=document.querySelector('#cart'),backdrop=document.querySelector('#overlay'),floating=document.querySelector('#floatingCart');cart.classList.toggle('open',open);backdrop.classList.toggle('show',open);floating.classList.toggle('hidden',open);cart.setAttribute('aria-hidden',String(!open));document.body.classList.toggle('cartOpen',open)}

document.addEventListener('click',event=>{
  const close=event.target.closest('[data-close-cart]');
  if(close){openCart(false);return}
  const homeCombo=event.target.closest('[data-home-combo]');
  if(homeCombo&&!event.target.closest('button,input,summary,details,a')){
    const comboDetails=homeCombo.querySelector('.homeComboDetails');
    if(comboDetails)comboDetails.open=!comboDetails.open;
    return
  }
  const step=event.target.closest('[data-card-step]');
  if(step){const input=step.parentElement.querySelector('input');input.value=Math.max(0,Math.min(999,(Number(input.value)||0)+Number(step.dataset.cardStep)));return}
  const add=event.target.closest('[data-add-quantities]');
  if(add){
    const composer=add.closest('.orderComposer'),id=add.dataset.addQuantities;
    let added=0;
    composer.querySelectorAll('[data-amount-format]').forEach(input=>{const amount=Math.max(0,Math.min(999,Number(input.value)||0));if(!amount)return;const key=`${id}:${input.dataset.amountFormat}`;basket[key]=(basket[key]||0)+amount;added+=amount;input.value=0});
    const hint=composer.querySelector('.amountHint');
    if(!added){hint.textContent='Elegí al menos una cantidad.';hint.classList.add('error');return}
    hint.textContent='Agregado al pedido ✓';hint.classList.remove('error');hint.classList.add('success');save();
    const label=add.textContent;add.textContent='Agregado ✓';add.classList.add('added');window.setTimeout(()=>{add.textContent=label;add.classList.remove('added');hint.textContent=composer.dataset.defaultHint;hint.classList.remove('success')},1400);return
  }
  const quantity=event.target.closest('[data-qty]');
  if(quantity){const key=quantity.dataset.qty;basket[key]=(basket[key]||0)+Number(quantity.dataset.d);if(basket[key]<=0)delete basket[key];save();return}
  const brand=event.target.closest('[data-brand-filter]');
  if(brand){activeBrand=brand.dataset.brandFilter;visibleLimit=30;renderBrandFilter();renderCatalog();return}
  const buyer=event.target.closest('[data-buyer]');
  if(buyer){buyerMode=buyer.dataset.buyer;activeView='Todos';activeSubcategory='all';activeDetail='all';query='';search.value='';visibleLimit=30;renderSubcategoryTabs();renderCatalog();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'});return}
  const view=event.target.closest('[data-view]');
  if(view){buyerMode='';query='';search.value='';activeView=view.dataset.view;activeSubcategory='all';activeDetail='all';visibleLimit=30;renderSubcategoryTabs();renderCatalog();return}
  const sub=event.target.closest('[data-subcategory]');
  if(sub){activeSubcategory=sub.dataset.subcategory;activeDetail='all';visibleLimit=30;document.querySelectorAll('[data-subcategory]').forEach(button=>button.classList.toggle('active',button===sub));renderDetailTabs();renderCatalog();return}
  const detail=event.target.closest('[data-detail]');
  if(detail){activeDetail=detail.dataset.detail;visibleLimit=30;document.querySelectorAll('[data-detail]').forEach(button=>button.classList.toggle('active',button===detail));renderCatalog()}
});
document.addEventListener('click',event=>{if(event.target.closest('[data-view],[data-buyer]'))activeBrand='all'},true);
document.querySelector('#searchBtn').onclick=()=>{document.querySelector('#catalogo').scrollIntoView();document.querySelector('#search').focus()};document.querySelector('#cartBtn').onclick=document.querySelector('#floatingCart').onclick=()=>openCart();document.querySelector('#closeCart').onclick=document.querySelector('#overlay').onclick=()=>openCart(false);document.addEventListener('keydown',event=>{if(event.key==='Escape')openCart(false)});search.oninput=e=>{query=e.target.value.trim();visibleLimit=30;renderCatalog()};sort.onchange=e=>{sortMode=e.target.value;visibleLimit=30;renderCatalog()};purchaseType.onchange=e=>{purchaseMode=e.target.value;visibleLimit=30;renderCatalog()};loadMore.onclick=()=>{visibleLimit+=30;renderCatalog()};clearFilters.onclick=()=>{activeView='Alimentos';activeSubcategory='all';activeDetail='all';activeBrand='all';buyerMode='';purchaseMode='all';query='';sortMode='featured';search.value='';sort.value='featured';purchaseType.value='all';visibleLimit=30;renderSubcategoryTabs();renderCatalog()};
const orderEndpoint="https://pedidos-falucho-receptor.solwheeler3.chatgpt.site/api/orders";
checkout.onclick=async()=>{
  const entries=Object.entries(basket).map(([key,quantity])=>({key,quantity,...basketData(key)})).filter(e=>e.product&&e.price);
  if(!entries.length)return;
  const name=document.querySelector("#buyerName").value.trim(),location=document.querySelector("#buyerLocation").value.trim(),type=document.querySelector("#buyerType").value,delivery=document.querySelector("#deliveryType").value,notes=document.querySelector("#buyerNotes").value.trim(),error=document.querySelector("#checkoutError");
  if(!name||!location){error.textContent="Completá tu nombre y localidad para enviar el pedido.";error.hidden=false;(!name?document.querySelector("#buyerName"):document.querySelector("#buyerLocation")).focus();return}
  error.hidden=true;
  const lines=entries.map(({quantity,product,format,price})=>"• "+quantity+" x "+product.name+" ("+productFormat(product,format)+") — "+money(price*quantity)),total=entries.reduce((sum,item)=>sum+item.price*item.quantity,0),customer="Nombre: "+name+"\nLocalidad: "+location+"\nTipo de cliente: "+type+"\nEntrega: "+delivery+(notes?"\nObservaciones: "+notes:""),clientOrderId=localStorage.getItem("falucho-pending-order-id")||("web-"+Date.now()+"-"+Math.random().toString(36).slice(2,12));
  localStorage.setItem("falucho-pending-order-id",clientOrderId);
  checkout.disabled=true;
  try{
    const response=await fetch(orderEndpoint,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({clientOrderId,customerName:name,locality:location,buyerType:type,deliveryType:delivery,notes,total,items:entries.map(({quantity,product,format,price})=>({productCode:String(product.id),productName:product.name,format,quantity,unitsPerBox:format==='box'?product.boxQuantity||null:format==='pair'?2:null,price,lineTotal:price*quantity})),website:""})});
    const result=await response.json().catch(()=>({}));
    if(!response.ok||!result.ok)throw new Error(result.error||"No se pudo registrar el pedido");
    const message="Hola, quiero hacer este pedido:\n\n"+lines.join("\n")+"\n\nTotal estimado: "+money(total)+"\n\n"+customer+"\n\nReferencia del pedido: "+clientOrderId+"\n\n¿Me confirman stock, precio final y envío?";
    localStorage.setItem("falucho-buyer",JSON.stringify({name,location,type,delivery,notes}));
    localStorage.removeItem("falucho-pending-order-id");
    basket={};
    save();
    openCart(false);
    const whatsappUrl="https://wa.me/541164591826?text="+encodeURIComponent(message);
    window.location.assign(whatsappUrl);
  }catch(failure){
    error.textContent="No pudimos guardar el pedido. Probá nuevamente; el carrito quedó guardado.";
    error.hidden=false;
    console.error(failure);
  }finally{checkout.disabled=false}
};
document.addEventListener('click',event=>{const brandButton=event.target.closest('[data-brand-shop]');if(brandButton){buyerMode='';query='';search.value='';activeView='Todos';activeSubcategory='all';activeDetail='all';activeBrand=brandButton.dataset.brandShop;visibleLimit=30;renderSubcategoryTabs();renderCatalog();document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})}if(event.target.closest('.sectionLink'))document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'})});
const offerSignup=document.querySelector('#offerSignup');if(offerSignup)offerSignup.onsubmit=event=>{event.preventDefault();const name=document.querySelector('#offerName').value.trim(),phone=document.querySelector('#offerPhone').value.trim(),location=document.querySelector('#offerLocation').value.trim(),type=document.querySelector('#offerCustomerType').value;if(!name||!phone||!location)return;const message=`Hola, quiero recibir las ofertas de Esquina Falucho.\n\nNombre: ${name}\nWhatsApp: ${phone}\nLocalidad: ${location}\nTipo de cliente: ${type}`;window.location.assign('https://wa.me/541164591826?text='+encodeURIComponent(message))};
try{const savedBuyer=JSON.parse(localStorage.getItem('falucho-buyer')||'{}');document.querySelector('#buyerName').value=savedBuyer.name||'';document.querySelector('#buyerLocation').value=savedBuyer.location||'';document.querySelector('#buyerType').value=savedBuyer.type||'Hogar';document.querySelector('#deliveryType').value=savedBuyer.delivery||'A coordinar';document.querySelector('#buyerNotes').value=savedBuyer.notes||''}catch{}
renderHomeCombos();renderHomeHighlights();initHighlightRail();renderBrandShowcase();renderSubcategoryTabs();renderCatalog();renderCart();openCart(false);window.addEventListener('pageshow',()=>openCart(false));

const customComboForm=document.querySelector('#customComboForm');if(customComboForm)customComboForm.onsubmit=event=>{event.preventDefault();const request=document.querySelector('#customComboRequest').value.trim(),name=document.querySelector('#customComboName').value.trim();if(!request)return;const message=`Hola, quiero cotizar un combo personalizado.\n\n${name?`Nombre: ${name}\n`:''}Productos y cantidades:\n${request}\n\n¿Me confirman el precio y la disponibilidad?`;window.location.assign('https://wa.me/541164591826?text='+encodeURIComponent(message))};
